office reception?","tab_content":"<p>Small tweaks like adding plants, painting walls, and updating lighting fixtures can make a big difference.</p>","_id":"e42ae97"},{"tab_title":"Q3: In what ways does lighting shape the mood of a reception area?","tab_content":"<p>Lighting affects mood—warm light is warm and cozy, whereas bright light enhances concentration and professionalism.</p>","_id":"1012b8c"}],"border_width":{"unit":"px","size":2},"title_color":"#3E3E3E","title_padding":{"unit":"px","top":"16","right":"26","bottom":"16","left":"26","isLinked":false},"icon_align":"right","icon_color":"#3E3E3E","icon_active_color":"#FF9000","icon_space":{"unit":"px","size":0},"content_padding":{"unit":"px","top":"10","right":"26","bottom":"10","left":"26","isLinked":false},"tab_active_color":"#FF9000","element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out","__globals__":{"title_background":"globals/colors?id=cfa1f76","title_color":"globals/colors?id=primary","tab_active_color":"globals/colors?id=116ad20","title_typography_typography":"globals/typography?id=201bf26","icon_color":"globals/colors?id=primary","icon_active_color":"globals/colors?id=116ad20","content_background_color":"","content_color":"globals/colors?id=primary","content_typography_typography":"globals/typography?id=text","border_color":"globals/colors?id=4d462f5"},"border_color":"#0000001A","content_color":"#3E3E3E","content_typography_typography":"custom","content_typography_font_family":"Outfit","content_typography_font_size":{"unit":"px","size":18,"sizes":[]},"content_typography_font_size_tablet":{"unit":"px","size":15,"sizes":[]},"content_typography_font_size_mobile":{"unit":"px","size":16,"sizes":[]},"content_typography_font_weight":"300","content_typography_line_height":{"unit":"em","size":"","sizes":[]},"faq_schema":"yes","eael_image_masking_custom_clip_path":"clip-path: polygon(50% 0%, 80% 10%, 10